function codePointLength(v) {
  let length = 0;
  let index = 0;
  while (index < v.length) {
    const first = v.charCodeAt(index++);
    if (first >= 0xd800 && first <= 0xdbff && index < v.length) {
      const second = v.charCodeAt(index);
      if (second >= 0xdc00 && second <= 0xdfff) index++;
    }
    length++;
  }
  return length;
}
